            new Quote { Id = "https://es.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "La poesía nace del dolor. La alegría es un fin en sí misma.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "La Universidad debiera insistirnos en lo antiguo y en lo ajeno. Si insiste en lo propio y en lo contemporáneo, la Universidad es inútil, porque está ampliando una función que ya cumple la prensa.", Author = "Jorge Luis Borges" },
