            new Quote { Id = "https://es.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "No estoy seguro de que yo exista, en realidad. Soy todos los autores que he leído, toda la gente que he conocido, todas las mujeres que he amado. Todas las ciudades que he visitado, todos mis antepasados...", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "No hay placer más complejo que el pensamiento y a él nos entregamos.", Author = "Jorge Luis Borges" },
