            new Quote { Id = "https://es.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Nos acecha el cristal, si entre las cuatro paredes de la alcoba hay un espejo. Ya no estoy solo. Hay otro. Hay el reflejo que arma en el alba un sigiloso teatro.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "No soy ni un pensador ni un moralista, sino sencillamente un hombre de letras que refleja en sus escritos su propia confusión y el respetado sistema de confusiones que llamamos filosofía, en forma de literatura.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Nuestras nadas poco difieren; es trivial y fortuita la circunstancia de que tú seas el lector de estos ejercicios, y yo su redactor.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Ocurre entonces la emoción singular llamada belleza, ese misterio hermoso que no descifran ni la psicología ni la retórica.", Author = "Jorge Luis Borges" },
